    ]);
    return $response->withJson((new Altcha(SystemConfig::$server_key))->createChallenge(new ChallengeOptions(
      algorithm: Algorithm::SHA256,
      maxNumber: BaseChallengeOptions::DEFAULT_MAX_NUMBER,
